<div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="page-title">Purchases</h1><p class="page-subtitle">Track supplier orders from request through receiving.</p></div></div><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Supplier</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td>#<?= (int)$order['id'] ?></td><td><?= htmlspecialchars($order['supplier_name']??'Unassigned') ?></td><td><?= htmlspecialchars($order['order_date']) ?></td><td>$<?= number_format((float)$order['total_amount'],2) ?></td><td><form method="post" action="?controller=purchases&action=status" class="d-flex gap-2"><?= $this->csrfField() ?><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><select name="status" class="form-select form-select-sm" onchange="this.form.submit()"><option <?= $order['status']==='pending'?'selected':'' ?>>pending</option><option <?= $order['status']==='approved'?'selected':'' ?>>approved</option><option <?= $order['status']==='received'?'selected':'' ?>>received</option><option <?= $order['status']==='cancelled'?'selected':'' ?>>cancelled</option></select></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h5>New purchase order</h5><form method="post" action="?controller=purchases&action=create" class="vstack gap-3"><?= $this->csrfField() ?><select class="form-select" name="supplier_id"><option value="">Select supplier</option><?php foreach($suppliers as $s): ?><option value="<?= (int)$s['id'] ?>"><?= htmlspecialchars($s['company_name']) ?></option><?php endforeach; ?></select><input class="form-control" type="date" name="order_date" value="<?= date('Y-m-d') ?>"><input class="form-control" type="number" step="0.01" name="total_amount" placeholder="Total amount"><textarea class="form-control" name="remarks" placeholder="Remarks"></textarea><button class="btn btn-primary">Create order</button></form></div></div></div></div>
